message.content:
[
  {
    "pd_harm_distress": "My stomach drops just thinking about it",
    "sys_consequence_reasoning": "Nobody gets hurt if I act, and everybody dies if I don't",
    "ae_welfare_concern": "can't just stand there watching it happen",
    "pda_responsibility": "when my hand is right on the switch"
  },
  {
    "pd_harm_distress": "I'm shaking just imagining the noise that train would make",
    "sys_consequence_reasoning": "five lives saved is five lives saved",
    "ae_welfare_concern": "watching people die when I had a way to stop it",
    "pda_responsibility": "when I had a way to stop it"
  },
  {
    "pd_harm_distress": "my hands would probably tremble on that lever",
    "sys_consequence_reasoning": "An empty siding versus five workers isn't really a fair trade",
    "pda_responsibility": "not choosing is still a choice"
  },
  {
    "pd_harm_distress": "I feel sick even picturing this",
    "sys_consequence_reasoning": "the harm avoided for those five men so clearly outweighs",
    "ae_welfare_concern": "watching people die that pushes me toward the lever"
  },
  {
    "pd_decision_conflict": "I keep hesitating, imagining every way this could go wrong",
    "sys_consequence_reasoning": "Five workers keep their lives, no one in the siding is harmed",
    "pd_harm_distress": "My hands are cold just thinking about it",
    "ae_welfare_concern": "standing still helps no one at all"
  },
  {
    "pd_harm_distress": "This makes my chest tight",
    "sys_consequence_reasoning": "Five people live instead of dying",
    "pda_self_consequence_regret": "fear of a lifetime of regret"
  },
  {
    "pd_harm_distress": "I'm honestly terrified I'd freeze up",
    "sys_consequence_reasoning": "empty siding means basically zero cost, and the five workers gain everything"
  },
  {
    "pd_decision_conflict": "I keep asking myself what if the barrier fails",
    "pd_harm_distress": "fear crawling in my chest",
    "sys_consequence_reasoning": "five lives protected against an empty track taking the impact instead"
  },
  {
    "pd_harm_distress": "My throat tightens just picturing the scene",
    "sys_consequence_reasoning": "one outcome ends with five deaths, the other ends with none",
    "pda_responsibility": "choosing the worse outcome just because it means doing nothing"
  },
  {
    "pd_harm_distress": "I feel almost frozen thinking this through",
    "sys_consequence_reasoning": "an empty siding loses nothing, five living people lose everything",
    "pda_responsibility": "desperate not to be the reason five people died"
  }
]
